<div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="h3">Oportunidades comerciales</h1><p class="text-muted mb-0">Crea una oportunidad desde CRM → Gestionar consulta → Nueva oportunidad.</p></div><a class="btn btn-outline-primary" href="<?= BASE_URL ?>/crm">Ir al CRM</a></div>
<section class="mb-4"><h2 class="h5">Resumen de la cartera completa</h2><p class="small text-muted">Los filtros del listado no cambian estos totales. <?= $user['rol']==='vendedor' ? 'Solo consultas actualmente asignadas a tu cuenta.' : 'Consultas del equipo.' ?></p><div class="row g-3"><?php foreach (Opportunity::STAGES as $key=>$label): ?><div class="col-6 col-lg-3"><a class="card card-body h-100 text-decoration-none text-dark" href="<?= BASE_URL ?>/opportunities?etapa=<?= e($key) ?>"><span class="small text-muted"><?= e($label) ?></span><strong class="display-6"><?= (int)($summary['counts'][$key] ?? 0) ?></strong></a></div><?php endforeach; ?></div></section>
<section class="card card-body mb-4"><h2 class="h5">Estimación de oportunidades abiertas activas</h2><p class="small text-muted">Monto ponderado = monto estimado × probabilidad / 100. Solo consultas abiertas e inmuebles activos disponibles o reservados. Ventas, rentas mensuales y monedas se calculan por separado. Son estimaciones del equipo, no ingresos cobrados.</p><?php if (!$summary['amounts']): ?><p class="text-muted mb-0">No hay oportunidades abiertas elegibles para estimar.</p><?php else: ?><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Operación</th><th>Moneda</th><th>Oportunidades</th><th>Monto estimado</th><th>Monto ponderado</th></tr></thead><tbody><?php foreach ($summary['amounts'] as $item): ?><tr><td><?= e(Closing::TYPES[$item['tipo']]) ?><?= $item['tipo']==='alquiler' ? ' (renta mensual)' : '' ?></td><td><?= e($item['moneda']) ?></td><td><?= (int)$item['total'] ?></td><td><?= number_format((float)$item['monto'],0) ?></td><td><?= number_format((float)$item['ponderado'],2) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<form class="card card-body mb-4" method="get" action="<?= BASE_URL ?>/opportunities"><div class="row g-3"><div class="col-md-7"><label class="form-label" for="q">Cliente o inmueble</label><input class="form-control" id="q" name="q" maxlength="160" value="<?= e($query) ?>"></div><div class="col-md-3"><label class="form-label" for="etapa">Estado</label><select class="form-select" id="etapa" name="etapa"><option value="">Todos</option><?php foreach (Opportunity::STAGES as $key=>$label): ?><option value="<?= e($key) ?>" <?= $stage===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary">Filtrar</button></div></div></form>
<?php if (!$rows): ?><div class="card card-body text-center py-5">No hay oportunidades para estos filtros.</div><?php else: ?><div class="card table-responsive"><table class="table align-middle mb-0"><thead><tr><th scope="col">N.º</th><th>Cliente / Inmueble</th><th>Vendedor</th><th>Estimado</th><th>Probabilidad</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php $rowNumber = 0; foreach ($rows as $item): ?><tr><th scope="row" class="text-muted text-center"><?= ++$rowNumber ?></th><td><strong><?= e($item['cliente']) ?></strong><div class="small text-muted"><?= e($item['titulo']) ?> · <?= e(Closing::TYPES[$item['tipo']]) ?></div><?php if ($item['etapa']==='abierta' && (!$item['propiedad_activa'] || !in_array($item['disponibilidad'],['disponible','reservado'],true) || in_array($item['lead_etapa'],['cerrado','perdido'],true))): ?><div class="small text-danger">Revisar estado: consulta o inmueble no elegible para estimación.</div><?php endif; ?></td><td><?= e($item['vendedor'] ?? 'Sin asignar') ?></td><td><?= e($item['moneda']) ?> <?= number_format((float)$item['monto_estimado'],0) ?><?= $item['tipo']==='alquiler' ? ' / mes' : '' ?></td><td><?= (int)$item['probabilidad'] ?>%</td><td><span class="badge <?= $item['etapa']==='ganada' ? 'text-bg-success' : ($item['etapa']==='abierta' ? 'text-bg-info' : 'text-bg-secondary') ?>"><?= e(Opportunity::STAGES[$item['etapa']]) ?></span></td><td><a class="btn btn-sm btn-outline-primary" href="<?= BASE_URL ?>/opportunities/edit?id=<?= (int)$item['id'] ?>">Gestionar</a></td></tr><?php endforeach; ?></tbody></table></div><p class="small text-muted mt-2">Hasta 100 oportunidades, ordenadas por última actualización. Los totales de la cartera no se limitan a estos registros.</p><?php endif; ?>
